    $scope.GetAdditionalApptdetail = function () {
        $scope.mainPatientProfileObj.AppointmentId = $scope.mainPatientProfileObj.AppointmentId || 0;
        loadAppointmentCallLogs();
        eHnoteMainAppointmentService.getAdditionalApptDetailsById($scope.mainPatientProfileObj.AppointmentId).then(function (resp) {
            $scope.PreAuthObj.PreAuthDetails = resp.data[0].AppointmentPreAuthDetails || [];

            $scope.AppointmentNotesArray = resp.data[0].AppointmentNotes || [];
            if ($scope.AppointmentNotesArray.length > 0) {
                var count = 0
                $scope.IsshowNotes = false;
                angular.forEach($scope.AppointmentNotesArray, function (aitem) {
                    if (aitem.Notes !== '') {
                        aitem.IsNotes = true;
                        count++;
                    }
                    else {
                        aitem.IsNotes = false;
                    }
                });
                if (count > 0) {
                    $scope.IsshowNotes = true;
                }
            }

            if (resp.data[0].AppointmentDetails.length > 0) {
                $scope.SelectedAppointmentObj.InformantId = resp.data[0].AppointmentDetails[0].InformantId || 0;

                $scope.SelectedAppointmentObj.OtherNotes = resp.data[0].AppointmentDetails[0].OtherNotes || "";
                $scope.SelectedAppointmentObj.OtherNotesCreatedBy = resp.data[0].AppointmentDetails[0].ModifiedBy || "";
                $scope.SelectedAppointmentObj.OtherNotesCreatedDt = resp.data[0].AppointmentDetails[0].ModifiedDt || "";

                var tmpd1 = $filter('date')(resp.data[0].AppointmentDetails[0].AppointmentDate, "yyyy-MM-dd");
                var tmpd2 = $filter('date')(new Date(), "yyyy-MM-dd");

                let isPastDate = false;
                if (tmpd2 > tmpd1) {
                    isPastDate = true;
                }
                if (isPastDate && resp.data[0].AppointmentDetails[0].IsNoShowAppointment) {
                    $scope.SelectedAppointmentObj.IsNoShowIconInd = true;
                } else {
                    $scope.SelectedAppointmentObj.IsNoShowIconInd = false;
                }
            }
            if (resp.data[0].PatientInsuranceList.length > 0) {
                $scope.SelectedAppointmentObj.PatientInsuranceList = resp.data[0].PatientInsuranceList || [];
            }

            $scope.mainobj.AppointmentInsuranceList =
                resp.data[0]?.AppointmentInsuranceList || [];
           
            if (resp.data[0].Patient != undefined) {
                $scope.PatientApptPCPInfo.ExternalComanagerName = resp.data[0].Patient.ExternalComanagerName || "";
                $scope.PatientApptPCPInfo.InternalComanagerName = resp.data[0].Patient.InternalComanagerName || "";
                $scope.PatientApptPCPInfo.InternalComanagerId = resp.data[0].Patient.InternalComanagerId || 0;
                $scope.PatientApptPCPInfo.ExternalComanagerId = resp.data[0].Patient.ExternalComanagerId || 0;
                $scope.PatientApptPCPInfo.ReferralName = resp.data[0].Patient.ReferralName || "";
                $scope.PatientApptPCPInfo.PCPDoctorName = resp.data[0].Patient.PCPDoctorName || "";
                $scope.PatientApptPCPInfo.HospitalReferenceId = resp.data[0].Patient.HospitalReferenceId || "";
                $scope.PatientApptPCPInfo.ReferenceNotes = resp.data[0].Patient.ReferenceNotes || "";

            }
        }, function (err) {
            alertify.error("Getting data failed");
        });
    }

