    $scope.VisitCardprint = function (string) {

        if ($scope.VisitCardApptobj.IsEnableCheckbox == true) {
            var count = 0;
            angular.forEach($scope.UpcomingAppointmentsArray, function (item) {
                if (item.IsVisitcardCheckBox == true) {
                    count++;
                }
            });
            if (count == 0) {
                alertify.error("Please Select An Up-coming Appointment");
                return;
            }
        }

        if ($scope.UpcomingAppointmentsArray.length == 0) {
            alertify.error("There is no Upcoming Appointments");
            return;
        }

        var ClincalDoctorsList = $filter("filter")($scope.mainPatientProfileObj.AllUsersList, function (item) {
            return item.RoleId === 1 || item.RoleId === 43;
        });

        var obj = {
            "patientinfo": angular.copy($scope.PatientDetailsInfo),
            "organizationLogo": $scope.OrganizationBase64LogoUrl || "",
            "UpcomingAppointment": [],
            "AllDoctorsList": ClincalDoctorsList || [],
            "BranchAddress": {
                "HospitalContact": doctorinfo.doctordata.UserAddress[0].MobileNo,
                "Address1": doctorinfo.doctordata.UserAddress[0].Address1 || "",
                "Address2": doctorinfo.doctordata.UserAddress[0].Address2 || "",
                "Location": doctorinfo.doctordata.UserAddress[0].Location || "",
                "StateName": doctorinfo.doctordata.UserAddress[0].StateName || "",
                "PinCode": doctorinfo.doctordata.UserAddress[0].PinCode,
                "CountryName": doctorinfo.doctordata.UserAddress[0].CountryName,
                "CityName": doctorinfo.doctordata.UserAddress[0].CityName,
                "DistrictRegion": doctorinfo.doctordata.UserAddress[0].DistrictRegion,
                "Latitude": doctorinfo.doctordata.UserAddress[0].Latitude,
                "Longitude": doctorinfo.doctordata.UserAddress[0].Longitude,
                "WebsiteUrl": doctorinfo.doctordata.UserAddress[0].NavigationURL || ""
            },
        };
        var today = $filter("date")(new Date(), "yyyy-MM-dd");
        if ($scope.UpcomingAppointmentsArray.length > 0) {
            if ($scope.VisitCardApptobj.IsEnableCheckbox == false) {
                var filter = $filter("filter")($scope.UpcomingAppointmentsArray, function (iterator, ind) { return iterator.ConsultationDt !== today; }) || [];
                if (filter.length > 0) {
                    obj.UpcomingAppointment = angular.copy(filter);
                    angular.forEach(obj.UpcomingAppointment, function (item) {
                        item.shortdate = $filter('date')(new Date(item.AppointmentDate + " " + "00:00:00"), "MM-dd-yyyy"); //item.ConsultationDt
                        item.shorttime = $filter('date')(new Date(item.AppointmentDate + " " + item.StartTime), "hh:mm a");
                    });
                }
            } else {
                var filter = $filter("filter")($scope.UpcomingAppointmentsArray, function (iterator, ind) { return iterator.IsVisitcardCheckBox == true; }) || [];
                if (filter.length > 0) {
                    obj.UpcomingAppointment = angular.copy(filter);
                    angular.forEach(obj.UpcomingAppointment, function (item) {
                        item.shortdate = $filter('date')(new Date(item.AppointmentDate + " " + "00:00:00"), "MM-dd-yyyy");
                        item.shorttime = $filter('date')(new Date(item.AppointmentDate + " " + item.StartTime), "hh:mm a");
                    });
                }
            }
        }

        USPrintService.generateVisitCardPrint(obj);
        $scope.AddUpdatePrintlog(string);
        angular.forEach($scope.UpcomingAppointmentsArray, function (item) {
            item.IsVisitcardCheckBox = false;
        });
        $scope.VisitCardApptobj.IsEnableCheckbox = false;
    }

