    $scope.PatientDemographicPrint = function (string, item) {

        var AppointmentId = $scope.mainPatientProfileObj.AppointmentId || 0;
        var ConsultationId = $scope.mainPatientProfileObj.VisitId || 0;

        let obj = {
            "PatientId": $scope.cacheStorageItem.patientid,
            "OrganizationId": $scope.HospitalId,
            "StatusId": 1
        };

        $q.all([
            eHnoteMainAppointmentService.GetAppointmentActiveDiagnosis(AppointmentId, ConsultationId),
            eHnoteInsuranceService.GetPatientAlertsNew(obj)
        ]).then(function (resp) {

            if (resp[0].data.status == "Success") {
                $scope.DiagnosisArray = resp[0].data.rows || [];
                $scope.PatientApptInsuInfo = item.PatientInsuranceList || [];
                $scope.InsurenceItemPrint = [];

                if ($scope.PatientApptInsuInfo.length > 0) {
                    angular.forEach($scope.PatientApptInsuInfo, function (item) {
                        let PrintPatientInsuranceDetailId = $filter("filter")($scope.PatientInsuranceSummary, function (fitem) {
                            return fitem.PatientInsuranceDetailId === item.PatientInsuranceDetailId;
                        });
                        if (PrintPatientInsuranceDetailId.length > 0) {
                            $scope.InsurenceItemPrint.push(PrintPatientInsuranceDetailId[0]);
                        }
                    });
                }

                if ($scope.ExpiredPatientInsuranceList.length > 0) {
                    angular.forEach($scope.PatientApptInsuInfo, function (pitem) {
                        let PrintPatientInsuranceDetailId = $filter("filter")($scope.ExpiredPatientInsuranceList, function (fitem) {
                            return fitem.PatientInsuranceDetailId === pitem.PatientInsuranceDetailId;
                        });
                        if (PrintPatientInsuranceDetailId.length > 0) {
                            $scope.InsurenceItemPrint.push(PrintPatientInsuranceDetailId[0]);
                        }
                    });
                }

                $scope.mainPatientProfileObj.AppointmentDate = $filter('date')($scope.mainPatientProfileObj.AppointmentDate, "MM-dd-yyyy");
                $scope.SelectedAppointmentObj.StartTime = $scope.SelectedAppointmentObj.StartTime || '';
                if ($scope.SelectedAppointmentObj.StartTime != '') {
                    $scope.SelectedAppointmentObj.StartTime = moment($scope.SelectedAppointmentObj.StartTime, "HH:mm").format("hh:mm A");
                }

                $scope.DoctorSignature = "";
                if ($scope.SelectedAppointmentObj != undefined) {
                    var TempArray = $filter("filter")($scope.allUserList, { "DoctorID": $scope.SelectedAppointmentObj.AppointmentDoctorId }, true) || [];
                    if (TempArray.length > 0) {
                        if (TempArray[0].SuffixId == 10 || TempArray[0].SuffixId == 13) {
                            $scope.DoctorSignature = TempArray[0].SignatureOfUser || '';
                        }
                    }
                    $scope.AppointmentDoctor = '';
                    $scope.DoctorArray = $filter("filter")($scope.allUserList, { "DoctorID": $scope.SelectedAppointmentObj.AppointmentDoctorId }, true) || [];
                    if ($scope.DoctorArray.length > 0) {
                        $scope.AppointmentDoctor = $scope.DoctorArray[0].FullName;
                    }
                }
            }

            if (resp[1].data.Status == "Success") {
                if (resp[1].data.rows.length > 0) {
                    $scope.PatientAlertsList = angular.copy(resp[1].data.rows) || [];
                    $scope.LatestpatientNotes = [$scope.PatientAlertsList[0]];
                } else {
                    $scope.LatestpatientNotes = [];
                }
            } else {
                alertify.error(resp.data.Message);
            }

           
            var Obj = {
                "PatientBaseInfo": angular.copy($scope.PatientDetailsInfo),
                "Addressinfo": $scope.PatientAddressSummary,
                "DesignationInfo": $scope.PatientApptPCPInfo || "",
                "Demographicinfo": $scope.DemographicSummary || "",
                "insuranceinfo": angular.copy($scope.InsurenceItemPrint) || [],
                "PatientImg": $scope.PatientProfileImageBase64 || "",
                "PatientNotes": angular.copy($scope.LatestpatientNotes) || [],
                "LanguageName": $scope.DemographicSummary.LanguageName || "",
                "VisitReason": $scope.mainPatientProfileObj.AppointmentVisitReasonName || '',
                "AppointmentNotesArray": $scope.AppointmentNotesArray || [],
                "AppointmentDate": $scope.mainPatientProfileObj.AppointmentDate,
                "AppointmentDoctor": $scope.AppointmentDoctor || '',
                "AppointmentTime": $scope.SelectedAppointmentObj.StartTime || '',
                "ExternalComanagerName": $scope.ExternalComanagerName || '',
                "InternalComanagerName": $scope.InternalComanagerName || '',
                "DiagnosisArray": $scope.DiagnosisArray || [],
                "DoctorSignatureURL": $scope.DoctorSignature || ''
            };

            Obj.PatientBaseInfo.PatientMobileNumber = $scope.PatientMobileNumber || "";
            Obj.PatientBaseInfo.PatientOfficeNumber = $scope.PatientOfficeNumber || "";
            Obj.PatientBaseInfo.EmailID = Obj.PatientBaseInfo.ContactInfo?.EmailID || "";

            if (Obj.insuranceinfo.length > 0) {
                angular.forEach(Obj.insuranceinfo, function (item) {
                    item.EligibilityStatusName = "";
                    item.frontbase64 = "";
                    var filter = $filter("filter")($scope.InsuranceStatusList1, { "StatusId": item.EligibilityStatusId }) || [];
                    if (filter.length > 0) {
                        item.EligibilityStatusName = filter[0].StatusName;
                    }
                    if (item.PatientDocumentDetails.length > 0) {
                        angular.forEach(item.PatientDocumentDetails, function (subitem) {
                            if (!subitem.IsBackSidefile) {
                                var filter1 = $filter("filter")($scope.PatientInsurancebase64, { "Documentid": subitem.DocumentId }) || [];
                                if (filter1.length > 0) {
                                    item.frontbase64 = filter1[0].frontbase64;
                                }
                            }
                        });
                    }
                });
            }

            console.log(Obj);

          
            USPrintService.generatePatientDemograpicPrint(Obj);
            $scope.AddUpdatePrintlog(string);

        });
    };






