                $scope.selectApptPCPimagelist = function ($files) {
                    $scope.PatientApptPCPInfo.PatientPCPDocuments = $scope.PatientApptPCPInfo.PatientPCPDocuments || [];
                    $scope.PatientApptPCPInfo.S3URL = '';
                    $scope.file = "";

                    $scope.file = $files;

                    if ($scope.file != null) {
                        if ($scope.file.length > 0) {
                            angular.forEach($scope.file, function (fitem) {
                                var pName = fitem.name, name = "";
                                var type = fitem.type.split("/")[1];
                                if (pName.length > 9) {
                                    name = pName.substring(0, 9) + "..." + "." + type;
                                } else {
                                    name = angular.copy(pName) + '.' + type;
                                }

                                var SelectedDate = $filter("date")(new Date(), "yyyy-MM-dd");
                                var obj = {
                                    "file": fitem,
                                    "FileTypeId": 10,
                                    "S3URL": "",
                                    "Remarks": "",
                                    "DeleteInd": "N",
                                    "DocumentID": 0,
                                    "SignedDate": SelectedDate,
                                    "DisplayName": fitem.name || "",
                                    "DocumentName": fitem.name || "",
                                    "FileName": fitem.name || "",
                                    "DocumentExt": fitem.type,
                                    "FileExt": fitem.type,
                                };


                                if (fitem.type != 'application/pdf') {
                                    $scope.PatientApptPCPInfo.PatientPCPDocuments.push(obj);
                                }
                                else {
                                    $scope.PatientApptPCPInfo.PatientPCPDocuments.push(obj);
                                }
                            });
                        }
                    }
                };


