    $scope.isApptPCPImageDoc = function (doc) {
        var ext = ((doc && (doc.DocumentExt || doc.FileExt)) || "").toString().toLowerCase().replace(/^\./, "");
        if (ext.indexOf("image/") === 0) {
            return ext !== "image/tiff";
        }
        return ["jpg", "jpeg", "png", "jfif", "gif", "bmp", "svg", "webp"].indexOf(ext) !== -1;
    };

