                    eHnoteCacheStorageService.addCacheStorage($scope.cacheStorageItem);
                    var filteredArray = resp.PatientFiles;
                    $scope.date_string = $filter("date")(new Date($scope.ChartObj.AppointmentDate), "MM-dd-yyyy");
