    $scope.selectparticularVisit = function (sitem, Mitem) {
        $scope.mainVisitObj.IsVisitListScreen = true;
        $scope.mainVisitObj.VisitScreen = "Summary";
        $scope.mainVisitObj.IscallconsulatationInd = false;
        $scope.mainVisitObj.AppointmentTab = 2;

        angular.forEach($scope.AllAppointmentsArray, function (uitem) {
            uitem.IsActive = false;
            if (uitem.AppointmentId == Mitem.AppointmentId) {
                uitem.IsActive = true;
            }
        });
        var SelectAppt = $filter("filter")($scope.AllAppointmentsArray, function (iterator) { return iterator.IsActive == true; }) || [];
        var selectedvisit = '';
        angular.forEach(SelectAppt[0].VisitsArray, function (subitem) {
            if (subitem.VisitId == sitem.VisitId) {
                selectedvisit = subitem || sitem;
            }
        });
        $scope.navtoselectparticularVisit(selectedvisit, SelectAppt[0]);
    };

