    $scope.navtoCheckInPopup = function (Mainitem) {

        if (Mainitem.BookingTypeId == 2) {
            alertify.error("Patient in waiting! Confirm appointment first. ");
            return false;
        }

        var todaydate = $filter('date')(new Date(), "yyyy-MM-dd");
        var futureDate = false;
        if (Mainitem.AppointmentDate > todaydate) {
            futureDate = true;
        }

        if (futureDate) {
            alertify.error("for future appointment Checkin/Checkout not allowed");
            return;
        }
        $scope.Technishionsend("NotCheckIN", Mainitem);
    };
    $scope.openpatientcheckinpopup = function (item, ind) {
        // If status is completed → open transfer popup directly
        if (item.ProfileStatusName === "Completed") {         
            $scope.navtoCheckInPopup(item);
            return; // Stop check-in popup
        }
        var resolveobj = {
            "PatientID": item.PatientId,
            "AppointmentID": item.AppointmentId,
            "BranchId": item.OrganizationId,
            "ConsultationDt": item.AppointmentDate,
            "DoctorID": item.AppointmentDoctorId,
            "AppointmentStatusId": item.AppointmentStatusId,
            "allUserList": $scope.allUserList || [],
            "AllBranchesList": $scope.mainPatientProfileObj.AllBranchesList || []
        };

        $scope.patientcheckinoutpopupinstance = $uibModal.open({
            "templateUrl": "templates/uibpopups/checkInCheckOutPopup.html",
            "backdrop": "static",
            "scope": $scope,
            "keyboard": false,
            "windowClass": "modal__ninety--",
            "resolve": {
                "obj": function () {
                    return resolveobj;
                }
            },
            "controller": "UsPatientCheckinheckoutCtrl"
        });
        $scope.patientcheckinoutpopupinstance.result.then(function (resp) {
            console.log(resp);
            if (resp.CloseandOpenFlag) {
                if (item.VisitReasonStatus == "InActive") {
                    //alertify.error("Visit Reason Is In-Active !  Please Update Visit Reason");
                    //return false;
                }
                $scope.navtoCheckInPopup(item);
            };
            $scope.GetPatientNotesAlertsById();
        }, function (cancel) {
        });
    };

