    $scope.SendGlassRxEmail = function () {
        let selectedPatientData = eHnoteMasterDataService.getpatientData();
        if ($scope.eObj.PatientEmail == '') {
            alertify.error("Please Enter PatientEmail!");
            return false;
        }
        let CreatedByName = "";
        if (doctorinfo.doctordata.User.length > 0) {
            CreatedByName = doctorinfo.doctordata.User[0].FullName || "";
        }
        var AppointmentDoctor = '';
        $scope.DoctorArray = $filter("filter")($scope.allUserList, { "DoctorID": $scope.mainPatientProfileObj.AppointmentDoctorId }, true) || [];
        if ($scope.DoctorArray.length > 0) {
            AppointmentDoctor = $scope.DoctorArray[0].FullName;
        }
        var orgDetails = $scope.treatmentData?.[0]?.OrganizationDetails || [];
        var obj = {
            "CreatedBy": CreatedByName,
            "PatientID": $scope.patientid || 0,
            //"HospitalID": $scope.HospitalId || 0,
            "HospitalID": $scope.SelectedAppointmentObj.OrganizationId || 0,
            "ConsultationStartTime": $scope.cacheStorageItem.ConsultationStartTime || '',
            "PatientArray": $scope.treatmentData[0].PatientArray || [],
            "VisitReason": $scope.mainPatientProfileObj.AppointmentVisitReasonName || '',
            "AppointmentDoctor": AppointmentDoctor || '',
            "Address": doctorinfo.doctordata.UserAddress[0].Address1 + '  ' + doctorinfo.doctordata.UserAddress[0].Address2 || '',
            "GlassRxDetails": $scope.cacheStorageItem.FinalGlassRxRefractionDetails || [],
            "Name": selectedPatientData.Patient[0].FullName || '',
            "Age": $scope.PatientAge || '',
            "Gender": selectedPatientData.Patient[0].Gender || '',
            "PatientDisplayId": selectedPatientData.Patient[0].PatientDisplayId || '',
            "PatientDOB": selectedPatientData.Patient[0].DOB || '',
            "EhnoteLogoURL": orgDetails?.[0]?.OrganizationLogoUrl || '',
            "UserId": $scope.SelectedAppointmentObj.AppointmentDoctorId || 0,
            "EmailCommunicationEnabled":false,
            "EmailCommunicationProviderId":0,
        }
        angular.forEach(doctorinfo.doctordata.UserAddress, function (mitem) {
            if ($scope.SelectedAppointmentObj.OrganizationId == mitem.ClinicId) {
                obj.BranchName = mitem.ClinicName;  
                //var MobileNo = eHnoteUserDataService.UsMobileFormatChange(mitem.MobileNo);
                //var ContactNo = eHnoteUserDataService.UsMobileFormatChange(mitem.ContactNo);
                obj.BranchPhone = mitem.MobileNo + "," + mitem.ContactNo;
                obj.BranchEmail = mitem.BranchEmail;
                obj.BranchAddress = mitem.Address1 + "," + mitem.Address2 + "," + mitem.CityName + "," + mitem.StateName + "," + mitem.CountryName + "," + mitem.PinCode;
                obj.EmailCommunicationEnabled = mitem.EmailCommunicationEnabled;
                obj.EmailCommunicationProviderId = mitem.EmailCommunicationProviderId;
            }
        });
        
        obj.DoctorName = $scope.appointmentinfo.DoctorFullName;
        
        obj.emailAddresses = getMailStr($scope.eObj.PatientEmail, $scope.eObj.DoctorEmail, $scope.eObj.OtherEmail);
        obj.PatientName = $scope.appointmentinfo.PatientDetails.FullName ? $scope.appointmentinfo.PatientDetails.FullName : "";
        obj.PatientGender = $scope.cacheStorageItem.Gender || '',
            obj.ConsultationDt = $filter("date")(($scope.appointmentinfo.ConsultationDt), "MM-dd-yyyy") || "";
        $scope.appointmentinfo.Title = $scope.appointmentinfo.PatientDetails.Title ? $scope.appointmentinfo.PatientDetails.Title : "";
        if ($scope.appointmentinfo.Title !== "") {
            obj.PatientName = $scope.appointmentinfo.Title + "." + obj.PatientName;
        }
        $scope.appointmentinfo.PatientDetails.AgeInYears = $scope.appointmentinfo.PatientDetails.AgeInYears || "";
        if ($scope.appointmentinfo.PatientDetails.AgeInYears !== "") {
            obj.PatientAge = $scope.appointmentinfo.PatientDetails.AgeInYears + "Y" + " " + $scope.appointmentinfo.PatientDetails.AgeInMonths + "M";
        } else {
            obj.PatientAge = $scope.appointmentinfo.PatientDetails.AgeInMonths + "M";
        }
        obj.PatientDisplayId = $scope.appointmentinfo.PatientDetails.PatientDisplayId ? $scope.appointmentinfo.PatientDetails.PatientDisplayId : "";
        
        eHnotePatientVisitReasonServices.GlassRxSummaryEmail(obj).then(function (resp) {
            if (resp.data.Message === "Success") {
                alertify.success("Mail sent successfully");
                $scope.eObj.PatientEmail = "";
                $scope.eObj.DoctorEmail = "";
                $scope.eObj.OtherEmail = "";
                $scope.PopUpOnPlan.dismiss('cancel');
            }
        })
    }
