    function getAppointmentSuperBillDetails() {

        eHnoteDiagnosisDataServices.GetSuperBillDetailsByAppointmentId($scope.cacheStorageItem.AppointmentId, $scope.cacheStorageItem.ConsultationID).then(function (response) {
            console.log(response);
            if (response.data.Status == "Success") {
                if (response.data.rows.length > 0) {
                    let superbillitem = response.data.rows[0];
                    if ($scope.cacheStorageItem.SuperBillFinalObj != undefined) {
                        $scope.cacheStorageItem.SuperBillFinalObj.EncounterStatus = superbillitem.EncounterStatus || "NotSigned";
                        $scope.cacheStorageItem.SuperBillFinalObj.EncounterStatusId = superbillitem.EncounterStatusId || 7;
                        $scope.cacheStorageItem.SuperBillFinalObj.SuperBillId = superbillitem.SuperBillId;
                        $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes = superbillitem.SuperBillArray || [];
                        $scope.cacheStorageItem.SuperBillFinalObj.SuperBillRemarks = superbillitem.SuperBillRemarks || "";
                    }
                    else {
                        $scope.cacheStorageItem.SuperBillFinalObj = {
                            "SuperBillId": 0,
                            "SuperBillSuggestedCodes": [],
                            "SuperBillRemarks": "",
                            "EncounterStatus": "NotSigned",
                            "EncounterStatusId": 7,

                        };
                        $scope.cacheStorageItem.SuperBillFinalObj.SuperBillId = superbillitem.SuperBillId;
                        $scope.cacheStorageItem.SuperBillFinalObj.SuperBillSuggestedCodes = superbillitem.SuperBillArray || [];
                        $scope.cacheStorageItem.SuperBillFinalObj.SuperBillRemarks = superbillitem.SuperBillRemarks || "";
                    }
                } else {
                    $scope.cacheStorageItem.SuperBillFinalObj = {
                        "SuperBillId": 0,
                        "SuperBillSuggestedCodes": [],
                        "SuperBillRemarks": "",
                        "EncounterStatus": "NotSigned",
                        "EncounterStatusId": 7,
                    };
                }
            }
        });
    };
